"use strict";

// The SAME defect through the other target shape a corpus scan of real
// vendored packages actually finds: not a destructuring pattern, but an
// ELEMENT-ACCESS target whose INDEX expression calls a local function.
//
//     REGISTRY[keyFor(bail)] = "installed";
//
// `rollup`, `vite`, `chai` and `esquery` all ship statements of exactly
// this shape (`importedBindingsPerDependency[resolveFileName(dependency)] =
// ...`). Nothing local is rebound by it: it MUTATES a property of
// `REGISTRY`. The old collector recorded `REGISTRY`, `keyFor` AND `bail`,
// and the `bail` mark is what withdrew the RWF-016 cutoff below.
const danger = require("./danger");

function dangerousOp(input) {
  return danger.explode(input);
}

function safeOp(input) {
  return "safe:" + input;
}

function bail() {
  throw new Error("fast mode is not supported here");
}

function keyFor(fn) {
  return "handler:" + fn.name;
}

const REGISTRY = {};

// THE POISON, element-access form. Completes normally on every load.
REGISTRY[keyFor(bail)] = "installed";

if (process.env.FIXTURE_LIB_MODE === "fast") {
  module.exports = dangerousOp;
  // RWF-016's cutoff, unchanged: a bare call to a local callable whose
  // body can only throw ends module evaluation here.
  bail();
}

module.exports = safeOp;
